package com.enderio.enderio.content.conduits.network;

import com.enderio.core.common.graph.Network;
import com.enderio.enderio.api.EnderIORegistries;
import com.enderio.enderio.api.conduits.Conduit;
import com.enderio.enderio.api.conduits.ConduitType;
import com.enderio.enderio.api.conduits.network.ConduitNetworkContext;
import com.enderio.enderio.api.conduits.network.ConduitNetworkContextType;
import com.google.common.base.Preconditions;
import com.google.common.collect.HashMultimap;
import com.google.common.collect.Maps;
import com.google.common.collect.Multimap;
import com.mojang.datafixers.util.Pair;
import com.mojang.logging.LogUtils;
import com.mojang.serialization.Codec;
import net.minecraft.CrashReport;
import net.minecraft.ReportedException;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceKey;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.saveddata.SavedData;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.level.ChunkEvent;
import net.neoforged.neoforge.event.tick.LevelTickEvent;
import org.jetbrains.annotations.Nullable;
import org.slf4j.Logger;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

@EventBusSubscriber
public class ConduitNetworkSavedData extends SavedData {

    public static final Codec<ConduitNetworkSavedData> CODEC = ConduitNetworkImpl.CODEC.listOf()
            .xmap(ConduitNetworkSavedData::new, ConduitNetworkSavedData::getNetworks);

    private final Multimap<ConduitType<?, ?>, ConduitNetworkImpl> networks = HashMultimap.create();

    private final Multimap<Long, ConduitNetworkImpl> networksByChunk = HashMultimap.create();
    private final Multimap<ConduitNetworkImpl, Long> chunksByNetwork = HashMultimap.create();

    private final Map<Long, Boolean> tickingChunksMap = Maps.newHashMap();

    private final Map<ConduitType<?, ?>, Map<BlockPos, ConduitNodeImpl>> unloadedNodes = Maps.newHashMap();

    private static final String KEY_NEW_DATA = "Networks";

    public static ConduitNetworkSavedData get(ServerLevel level) {
        return level.getDataStorage()
                .computeIfAbsent(new Factory<>(ConduitNetworkSavedData::new, ConduitNetworkSavedData::load),
                        "enderio_conduit_network");
    }

    public ConduitNetworkSavedData() {
    }

    private ConduitNetworkSavedData(List<ConduitNetworkImpl> networks) {
        for (ConduitNetworkImpl network : networks) {
            // If a world has been loaded from 8.0.7 into 8.2.9 and then updated further, the conduit data has become corrupted.
            // In this instance, we'll have to discard the network and have it get repaired.
            // ConstantValue issues are because conduit() is supposed to be non null.
            //noinspection ConstantValue
            boolean anyNodesMissingConduit = network.nodes().stream().anyMatch(n -> n.conduit() == null);
            //noinspection ConstantValue
            if (anyNodesMissingConduit) {
                LOGGER.warn("Skipping network with damaged conduit data.");
                continue;
            }

            network.setOnChunkCoverageChanged(this::onNetworkChunksChanged);
            this.networks.put(network.conduitType(), network);

            for (var node : network.nodes()) {
                unloadedNodes.computeIfAbsent(network.conduitType(), c -> Maps.newHashMap()).put(node.pos(), node);
            }
        }
    }

    private static ConduitNetworkSavedData load(CompoundTag nbt, HolderLookup.Provider lookupProvider) {
        // TODO: 1.22 - remove support for the legacy graph format.
        if (nbt.contains(KEY_GRAPHS)) {
            return loadLegacy(nbt, lookupProvider);
        }

        var result = CODEC.parse(lookupProvider.createSerializationContext(NbtOps.INSTANCE), nbt.get(KEY_NEW_DATA));
        result.error().ifPresent(e -> LOGGER.error("Errors loading conduit network data, some networks may be missing: {}", e.message()));
        return result.getPartialOrThrow();
    }

    private List<ConduitNetworkImpl> getNetworks() {
        return networks.values().stream().filter(n -> n.isValid() && !n.isEmpty()).toList();
    }

    @Override
    public CompoundTag save(CompoundTag compoundTag, HolderLookup.Provider provider) {
        compoundTag.put(KEY_NEW_DATA,
                CODEC.encodeStart(provider.createSerializationContext(NbtOps.INSTANCE), this).getOrThrow());
        return compoundTag;
    }

    @Nullable
    public ConduitNodeImpl claimNode(Holder<Conduit<?, ?>> conduit, BlockPos pos) {
        var conduitMap = unloadedNodes.get(conduit.value().type());
        if (conduitMap == null) {
            LOGGER.warn("Conduit data is missing!");
            return null;
        }

        if (!conduitMap.containsKey(pos)) {
            LOGGER.warn("Conduit data is missing node at {}", pos);
            return null;
        }

        var node = conduitMap.remove(pos);
        if (node.conduit() != conduit) {
            // Trust block entity as source of truth *just* because it's easier to rebuild a node than it is to reconcile the block entity's data.
            LOGGER.warn("Conduit mismatch at {}: {} (network) vs {} (block entity). Dumping data, node will be rebuilt.", pos, node.conduit(), conduit);
            return null;
        }

        return node;
    }

    public void returnNode(Holder<Conduit<?, ?>> conduit, BlockPos pos, ConduitNodeImpl node) {
        unloadedNodes.computeIfAbsent(conduit.value().type(), c -> Maps.newHashMap()).put(pos, node);
    }

    public static void onNetworkCreated(ServerLevel level, ConduitNetworkImpl network) {
        get(level).onNetworkCreated(network);
    }

    private void onNetworkCreated(ConduitNetworkImpl network) {
        Preconditions.checkArgument(network.isValid(), "New network is not valid!");
        networks.put(network.conduitType(), network);
        onNetworkChunksChanged(network);
        network.setOnChunkCoverageChanged(this::onNetworkChunksChanged);
    }

    public static void onNetworkDiscarded(ServerLevel level, ConduitNetworkImpl network) {
        Preconditions.checkArgument(network.isDiscarded(), "Network is not discarded!");
        get(level).onNetworkDiscarded(network);
    }

    private void onNetworkDiscarded(ConduitNetworkImpl network) {
        // Allow empty or discarded networks here
        networks.remove(network.conduitType(), network);

        for (var chunk : network.allChunks()) {
            networksByChunk.remove(chunk, network);
            chunksByNetwork.remove(network, chunk);
        }
    }

    private void onNetworkChunksChanged(ConduitNetworkImpl network) {
        var knownChunks = chunksByNetwork.get(network);
        var currentChunks = network.allChunks();

        // Find removed chunks
        var removedChunks = knownChunks.stream().filter(chunk -> !currentChunks.contains(chunk)).toList();

        // Find added chunks
        var addedChunks = currentChunks.stream().filter(chunk -> !knownChunks.contains(chunk)).toList();

        // Update collections
        for (var chunk : removedChunks) {
            networksByChunk.remove(chunk, network);
        }

        for (var chunk : addedChunks) {
            networksByChunk.put(chunk, network);
        }

        chunksByNetwork.get(network).clear();
        chunksByNetwork.get(network).addAll(currentChunks);
    }

    @Override
    public boolean isDirty() {
        // Always save networks when the opportunity arises
        return true;
    }

    @SubscribeEvent
    public static void onLevelTick(LevelTickEvent.Post event) {
        if (event.getLevel() instanceof ServerLevel serverLevel) {
            get(serverLevel).tick(serverLevel);
        }
    }

    private void tick(ServerLevel serverLevel) {
        // Only remove empty graphs here
        networks.values()
                .stream()
                .filter(n -> !n.isValid() || n.isEmpty())
                .toList() // avoid CME
                .forEach(this::onNetworkDiscarded);

        // Detect any chunk load or tick state changes
        for (var chunkPos : networksByChunk.keySet()) {
            // Checking #hasChunk to resolve GH-1177. Unsure why hasChunk changes without firing a chunk unload event.
            boolean isTicking = serverLevel.hasChunk(ChunkPos.getX(chunkPos), ChunkPos.getZ(chunkPos)) && serverLevel.shouldTickBlocksAt(chunkPos);
            if (!tickingChunksMap.containsKey(chunkPos) || isTicking != tickingChunksMap.get(chunkPos)) {
                tickingChunksMap.put(chunkPos, isTicking);
                networksByChunk.get(chunkPos).forEach(n -> n.onChunkTickStatusChanged(chunkPos));
            }
        }

        for (var conduitType : networks.keySet()) {
            // Ensure caches are ready for any networks that require them
            if (conduitType.doesRequireNetworkCaches()) {
                for (var network : networks.get(conduitType)) {
                    network.ensureCachesReady();
                }
            }

            // Skip non-ticking graphs.
            var ticker = conduitType.ticker();
            if (ticker == null) {
                continue;
            }

            // TODO: GH-1269
            int conduitId = EnderIORegistries.CONDUIT_TYPE.getId(conduitType);
            for (var network : networks.get(conduitType)) {
                try {
                    ticker.tick(serverLevel, network, conduitId);
                } catch (Throwable t) {
                    var report = CrashReport.forThrowable(t, "Ticking conduit network");
                    var category = report.addCategory(EnderIORegistries.CONDUIT_TYPE.getKey(conduitType) + " network being ticked");
                    network.addCrashInfo(category);
                    throw new ReportedException(report);
                }
            }
        }
    }

    @SubscribeEvent
    public static void onChunkUnloaded(ChunkEvent.Unload event) {
        if (event.getLevel() instanceof ServerLevel serverLevel) {
            get(serverLevel).tickingChunksMap.remove(event.getChunk().getPos().toLong());
        }
    }

    // region Legacy Serialization

    private static final Logger LOGGER = LogUtils.getLogger();

    // TODO: 1.22 - Remove

    private static final String KEY_GRAPHS = "Graphs";
    private static final String KEY_TYPE = "Type";
    private static final String KEY_GRAPH_OBJECTS = "GraphObjects";
    private static final String KEY_GRAPH_CONNECTIONS = "GraphConnections";
    private static final String KEY_GRAPH_CONTEXT = "GraphContext";

    // TODO: Write it.

    private static ConduitNetworkSavedData loadLegacy(CompoundTag nbt, HolderLookup.Provider lookupProvider) {
        var savedData = new ConduitNetworkSavedData();

        ListTag graphsTag = nbt.getList(KEY_GRAPHS, Tag.TAG_COMPOUND);
        for (Tag tag : graphsTag) {
            CompoundTag typedGraphTag = (CompoundTag) tag;
            ResourceKey<Conduit<?, ?>> conduitKey = ResourceKey.create(EnderIORegistries.Keys.CONDUIT,
                    ResourceLocation.parse(typedGraphTag.getString(KEY_TYPE)));

            var registry = lookupProvider.lookupOrThrow(EnderIORegistries.Keys.CONDUIT);

            Optional<Holder.Reference<Conduit<?, ?>>> conduit = registry.get(conduitKey);

            if (conduit.isPresent()) {
                ListTag graphsForTypeTag = typedGraphTag.getList(KEY_GRAPHS, Tag.TAG_COMPOUND);
                deserializeGraphs(lookupProvider, conduit.get(), graphsForTypeTag, savedData);
            } else {
                LOGGER.warn("Skipping graph for missing conduit: {}", conduitKey);
            }
        }

        return savedData;
    }

    private static void deserializeGraphs(HolderLookup.Provider lookupProvider, Holder<Conduit<?, ?>> conduit,
            ListTag graphs, ConduitNetworkSavedData savedData) {
        for (Tag tag1 : graphs) {
            CompoundTag graphTag = (CompoundTag) tag1;

            ListTag graphObjectsTag = graphTag.getList(KEY_GRAPH_OBJECTS, Tag.TAG_COMPOUND);
            ListTag graphConnectionsTag = graphTag.getList(KEY_GRAPH_CONNECTIONS, Tag.TAG_COMPOUND);

            // Skip any graphs which have no objects in them, they should not have been
            // saved.
            if (graphObjectsTag.isEmpty()) {
                // TODO: Warning or something?
                continue;
            }

            // Load all nodes
            List<ConduitNodeImpl> nodes = new ArrayList<>();
            for (int i = 0; i < graphObjectsTag.size(); i++) {
                CompoundTag nodeTag = graphObjectsTag.getCompound(i);
                var node = ConduitNodeImpl.CODEC.decode(lookupProvider.createSerializationContext(NbtOps.INSTANCE), nodeTag)
                        .getOrThrow()
                        .getFirst();

                node.setConduitIfNull(conduit);

                nodes.add(node);
            }

            // Load all connection indices
            List<Pair<Integer, Integer>> connections = new ArrayList<>();
            for (Tag tag2 : graphConnectionsTag) {
                CompoundTag connectionTag = (CompoundTag) tag2;
                connections.add(new Pair<>(connectionTag.getInt("0"), connectionTag.getInt("1")));
            }

            // Load network context
            ConduitNetworkContext<?> context = null;
            if (graphTag.contains(KEY_GRAPH_CONTEXT)) {
                context = loadNetworkContext(lookupProvider, graphTag.getCompound(KEY_GRAPH_CONTEXT));
            }

            // Create network
            var network = new ConduitNetworkImpl(conduit.value().type(), Optional.ofNullable(context), nodes,
                    new Network.IndexedEdgeList(connections));

            // Ensure the nodes are all valid
            if (nodes.stream().anyMatch(n -> !n.isValid())) {
                LOGGER.error(
                        "Node(s) are still invalid after loading the network. Please report this issue to Ender IO, loading cannot continue.");
                throw new IllegalStateException("Graph was null after loading the conduit network");
            }

            // Hook onto chunk coverage change event
            network.setOnChunkCoverageChanged(savedData::onNetworkChunksChanged);

            savedData.networks.put(network.conduitType(), network);

            for (var node : network.nodes()) {
                savedData.unloadedNodes.computeIfAbsent(network.conduitType(), c -> Maps.newHashMap())
                        .put(node.pos(), node);
            }
        }
    }

    @Nullable
    private static ConduitNetworkContext<?> loadNetworkContext(HolderLookup.Provider lookupProvider,
            CompoundTag contextTag) {
        ResourceLocation serializerKey = ResourceLocation.parse(contextTag.getString("Type"));
        ConduitNetworkContextType<?> contextType = Objects.requireNonNull(
                EnderIORegistries.CONDUIT_NETWORK_CONTEXT_TYPE.get(serializerKey),
                "Unable to find conduit network context type with key " + serializerKey);

        if (contextType.codec() == null) {
            return null;
        }

        // TODO: We're using getOrThrow a lot for conduits. Should definitely make more
        // robust/flexible.
        CompoundTag data = contextTag.getCompound("Data");
        var ops = lookupProvider.createSerializationContext(NbtOps.INSTANCE);
        return contextType.codec().decode(ops, ops.getMap(data).getOrThrow()).getOrThrow();
    }

    // endregion
}

package com.enderio.enderio.content.conduits.network;

import com.enderio.core.common.graph.Network;
import com.enderio.enderio.api.EnderIORegistries;
import com.enderio.enderio.api.conduits.Conduit;
import com.enderio.enderio.api.conduits.ConduitType;
import com.enderio.enderio.api.conduits.connection.config.IOConnectionConfig;
import com.enderio.enderio.api.conduits.connection.ConduitBlockConnection;
import com.enderio.enderio.api.conduits.connection.path.ConduitConnectionPath;
import com.enderio.enderio.api.conduits.connection.path.ConnectionPathProperty;
import com.enderio.enderio.api.conduits.network.ConduitNetwork;
import com.enderio.enderio.api.conduits.network.ConduitNetworkContext;
import com.enderio.enderio.api.conduits.network.ConduitNetworkContextType;
import com.enderio.enderio.api.conduits.network.node.ConduitNode;
import com.enderio.enderio.content.conduits.network.pathing.ConduitPathingStrategy;
import com.enderio.enderio.content.conduits.network.pathing.PathfindingContext;
import com.enderio.enderio.content.conduits.network.pathing.BreadthFirstPathingStrategy;
import com.google.common.base.Preconditions;
import com.google.common.collect.ArrayListMultimap;
import com.google.common.collect.HashMultimap;
import com.google.common.collect.ListMultimap;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Multimap;
import com.google.common.collect.SetMultimap;
import com.google.common.collect.Sets;
import com.google.common.primitives.Ints;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.CrashReportCategory;
import net.minecraft.core.Direction;
import net.minecraft.core.Holder;
import net.minecraft.world.item.DyeColor;
import net.minecraft.world.level.ChunkPos;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class ConduitNetworkImpl extends Network<ConduitNetworkImpl, ConduitNodeImpl> implements ConduitNetwork, PathfindingContext {

    //Public for testing
    public static final Codec<ConduitNetworkImpl> LEGACY_CODEC = RecordCodecBuilder.create(instance -> instance
            .group(Conduit.CODEC.fieldOf("conduit").forGetter(i -> null),
                    ConduitNetworkContext.GENERIC_CODEC.optionalFieldOf("context")
                            .forGetter(i -> i.context == null || !i.context.type().isPersistent() ? Optional.empty()
                                    : Optional.of(i.context)))
            .and(graphCodec(instance, ConduitNodeImpl.CODEC))
            .apply(instance, ConduitNetworkImpl::new));

    //Public for testing
    public static final Codec<ConduitNetworkImpl> NEW_CODEC = RecordCodecBuilder.create(instance -> instance
            .group(ConduitType.CODEC.fieldOf("conduit_type").forGetter(i -> i.conduitType),
                    ConduitNetworkContext.GENERIC_CODEC.optionalFieldOf("context")
                            .forGetter(i -> i.context == null || !i.context.type().isPersistent() ? Optional.empty()
                                    : Optional.of(i.context)))
            .and(graphCodec(instance, ConduitNodeImpl.CODEC))
            .apply(instance, ConduitNetworkImpl::new));

    public static final Codec<ConduitNetworkImpl> CODEC = Codec.withAlternative(NEW_CODEC, LEGACY_CODEC);

    private final ConduitType<?, ?> conduitType;

    private final ConduitPathingStrategy pathfinder = new BreadthFirstPathingStrategy();

    @Nullable
    private ConduitNetworkContext<?> context;

    // TODO: Not final because onNodeAdded is called by super so we need to initialize on use
    //       I might be able to make minor changes to the Network class to fix this.
    private final Map<Holder<Conduit<?, ?>>, Integer> nodeCountByConduit = Maps.newHashMap();

    // Caches
    private final boolean supportsCaching;

    private boolean shouldRebuildCache = true;
    private boolean haveConnectionsChanged = true;
    private final Set<ConduitNodeImpl> dirtyNodes = Sets.newHashSet();

    private final Multimap<Long, ConduitNodeImpl> nodesByChunkPos = HashMultimap.create();

    private final Set<ConduitNodeImpl> tickingNodes = Sets.newHashSet();

    // TODO: Separate this into a list and a multimap so we can sort all endpointConnections?
    private final SetMultimap<ConduitNodeImpl, ConduitBlockConnection> endpointConnections = HashMultimap.create();
    private final Map<ConduitBlockConnection, List<ConduitConnectionPath>> accessiblePathsByConnection = Maps
            .newHashMap();

    private final List<ConduitBlockConnection> insertConnections = Lists.newArrayList();
    private final List<ConduitBlockConnection> extractConnections = Lists.newArrayList();

    private final Set<DyeColor> allChannels = Sets.newHashSet();
    private final ListMultimap<DyeColor, ConduitBlockConnection> insertConnectionsByChannel = ArrayListMultimap
            .create();
    private final ListMultimap<DyeColor, ConduitBlockConnection> extractConnectionsByChannel = ArrayListMultimap
            .create();

    private final Map<ConduitBlockConnection, List<ConduitConnectionPath>> extractConnectionsByInsert = Maps
            .newHashMap();
    private final Map<ConduitBlockConnection, List<ConduitConnectionPath>> insertConnectionsByExtract = Maps
            .newHashMap();

    private final ListMultimap<Integer, Holder<Conduit<?, ?>>> tickableConduits = ArrayListMultimap.create();
    private boolean areTickableConduitsValid = false;

    @Nullable
    private Consumer<ConduitNetworkImpl> onChunkCoverageChanged = null;

    public ConduitNetworkImpl(ConduitType<?, ?> conduitType, ConduitNodeImpl initialNode) {
        super(initialNode);
        this.conduitType = conduitType;
        this.supportsCaching = conduitType.doesRequireNetworkCaches();
        recomputeNodeCounts();
    }

    // TODO: Public for legacy deserialization
    public ConduitNetworkImpl(ConduitType<?, ?> conduitType, Optional<ConduitNetworkContext<?>> context,
                              List<ConduitNodeImpl> nodes, IndexedEdgeList edges) {
        super(nodes, edges);
        this.conduitType = conduitType;
        this.context = context.orElse(null);
        this.supportsCaching = conduitType.doesRequireNetworkCaches();
        recomputeNodeCounts();
    }

    @SuppressWarnings("OptionalUsedAsFieldOrParameterType")
    private ConduitNetworkImpl(Holder<Conduit<?, ?>> conduit, Optional<ConduitNetworkContext<?>> context,
                               List<ConduitNodeImpl> nodes, IndexedEdgeList edges) {
        super(nodes, edges);
        this.conduitType = conduit.value().type();
        this.context = context.orElse(null);
        this.supportsCaching = conduitType.doesRequireNetworkCaches();
        this.nodes().forEach(n -> n.setConduitIfNull(conduit));
        recomputeNodeCounts();
    }

    protected ConduitNetworkImpl(ConduitType<?, ?> conduitType) {
        this.conduitType = conduitType;
        this.supportsCaching = conduitType.doesRequireNetworkCaches();
    }

    @Override
    public ConduitType<?, ?> conduitType() {
        return conduitType;
    }

    @Override
    public Set<Holder<Conduit<?, ?>>> conduits() {
        if (nodeCountByConduit == null) {
            return Set.of();
        }

        return Collections.unmodifiableSet(nodeCountByConduit.keySet());
    }

    @Override
    public List<Holder<Conduit<?, ?>>> getTickableConduits(long gameTime, int tickOffset) {
        if (!areTickableConduitsValid && nodeCountByConduit != null) {
            tickableConduits.clear();

            // Check all conduits to see if they can tick
            for (var conduit : nodeCountByConduit.keySet()) {
                for (int i = 0; i < 20; i++) {
                    if (i % conduitType().getTickRate(conduit) == 0) {
                        tickableConduits.put(i, conduit);
                    }
                }
            }

            areTickableConduitsValid = true;
        }

        return tickableConduits.get(Ints.saturatedCast((gameTime + tickOffset) % 20));
    }

    // region Chunk Tracking

    public Set<Long> allChunks() {
        return nodesByChunkPos.keySet();
    }

    public void setOnChunkCoverageChanged(Consumer<ConduitNetworkImpl> onChunkCoverageChanged) {
        this.onChunkCoverageChanged = onChunkCoverageChanged;
    }

    // endregion

    // region Queries

    @Override
    public int nodeCount(Holder<Conduit<?, ?>> conduit) {
        return nodeCountByConduit.getOrDefault(conduit, 0);
    }

    private void recomputeNodeCounts() {
        nodeCountByConduit.clear();
        for (var node : nodes()) {
            nodeCountByConduit.compute(node.conduit(), (k, count) -> count == null ? 1 : count + 1);
        }
    }

    // These are unfortunately necessary for the IConduitNetwork interface.
    @Override
    public boolean contains(ConduitNode node) {
        if (node instanceof ConduitNodeImpl typedNode) {
            return contains(typedNode);
        }

        return false;
    }

    @Override
    public Set<? extends ConduitNode> neighbors(ConduitNode node) {
        if (node instanceof ConduitNodeImpl typedNode) {
            return neighbors(typedNode);
        }

        return Set.of();
    }

    public Collection<ConduitNodeImpl> tickingNodes() {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return Collections.unmodifiableCollection(tickingNodes);
    }

    public Collection<ConduitNodeImpl> blockEndpoints() {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return Collections.unmodifiableCollection(endpointConnections.keySet());
    }

    public Collection<ConduitBlockConnection> blockConnections() {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return Collections.unmodifiableCollection(endpointConnections.values());
    }

    // This is sorted
    public List<ConduitConnectionPath> blockConnectionsAccessibleFrom(ConduitBlockConnection connection) {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return accessiblePathsByConnection.getOrDefault(connection, List.of());
    }

    public Set<DyeColor> allChannels() {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return allChannels;
    }

    public List<ConduitBlockConnection> insertConnections() {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return Collections.unmodifiableList(insertConnections);
    }

    public List<ConduitBlockConnection> insertConnections(DyeColor color) {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return insertConnectionsByChannel.get(color);
    }

    // This is sorted
    public List<ConduitConnectionPath> extractConnectionsFrom(ConduitBlockConnection insertConnection) {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return extractConnectionsByInsert.getOrDefault(insertConnection, List.of());
    }

    public List<ConduitBlockConnection> extractConnections() {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return Collections.unmodifiableList(extractConnections);
    }

    public List<ConduitBlockConnection> extractConnections(DyeColor color) {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return extractConnectionsByChannel.get(color);
    }

    // This is sorted
    public List<ConduitConnectionPath> insertConnectionsFrom(ConduitBlockConnection extractConnection) {
        ensureNotDiscarded();
        Preconditions.checkState(supportsCaching, "This conduit does not support caching");
        return insertConnectionsByExtract.getOrDefault(extractConnection, List.of());
    }

    // endregion

    // region Context

    public boolean hasContext(ConduitNetworkContextType<?> type) {
        ensureNotDiscarded();
        return context != null && context.type() == type;
    }

    @SuppressWarnings("unchecked")
    public <C extends ConduitNetworkContext<C>> @Nullable C getContext(ConduitNetworkContextType<C> type) {
        ensureNotDiscarded();
        if (context != null && context.type() == type) {
            return (C) context;
        }

        return null;
    }

    @SuppressWarnings("unchecked")
    public <C extends ConduitNetworkContext<C>> C getOrCreateContext(ConduitNetworkContextType<C> type) {
        ensureNotDiscarded();
        if (context != null && context.type() == type) {
            return (C) context;
        }

        context = type.factory().get();
        return (C) context;
    }

    // endregion

    // region Cache Updates

    /**
     * Call this before ticking the network to ensure caches are up-to-date.
     * We use this to defer cache rebuilds to the last possible moment to ensure network mutations are less expensive.
     */
    public void ensureCachesReady() {
        ensureNotDiscarded();

        // Shouldn't be called, but can't hurt to be safe.
        if (!supportsCaching) {
            return;
        }

        if (shouldRebuildCache) {
            rebuildCache();
        } else {
            for (var node : dirtyNodes) {
                if (node.isTicking()) {
                    // Update nodes by removing and adding again.
                    if (tickingNodes.contains(node)) {
                        removeTickingNode(node);
                    }

                    addTickingNode(node);
                } else if (tickingNodes.contains(node)) {
                    removeTickingNode(node);
                }
            }

            dirtyNodes.clear();
        }

        if (haveConnectionsChanged) {
            updateChannelList();
            sortConnectionLists();
        }
    }

    public void onNodeUpdated(ConduitNodeImpl node) {
        if (supportsCaching && !shouldRebuildCache) {
            dirtyNodes.add(node);
        }
    }

    public void onChunkTickStatusChanged(long chunk) {
        if (!supportsCaching || shouldRebuildCache) {
            return;
        }

        dirtyNodes.addAll(nodesByChunkPos.get(chunk));
    }

    // endregion

    // region Caching Logic

    private void addTickingNode(ConduitNodeImpl node) {
        tickingNodes.add(node);

        for (var side : Direction.values()) {
            if (!node.isConnectedToBlock(side)) {
                continue;
            }

            var connection = new ConduitBlockConnection(node, side);
            endpointConnections.put(node, connection);

            // Add own list of block connection accesses.
            accessiblePathsByConnection.computeIfAbsent(connection,
                    k -> new ArrayList<>(endpointConnections.values().size()));

            // Add all paths to both lists
            for (var accessibleConnection : endpointConnections.values()) {
                if (accessibleConnection != connection) {
                    findBestPathTo(connection, accessibleConnection).ifPresent(path -> {
                        var accessibleConnections = accessiblePathsByConnection.get(connection);
                        if (!accessibleConnections.contains(path)) {
                            accessibleConnections.add(path);
                        }

                        var reverseAccessibleConnections = accessiblePathsByConnection.get(accessibleConnection);
                        if (!reverseAccessibleConnections.contains(path.reverse())) {
                            reverseAccessibleConnections.add(path.reverse());
                        }
                    });
                }
            }

            // Handle IO caching
            var config = node.getConnectionConfig(side);
            if (config instanceof IOConnectionConfig ioConnectionConfig) {
                // First add sending and receiving connections
                boolean canInsert = ioConnectionConfig.canInsert(node::hasRedstoneSignal);
                boolean canExtract = ioConnectionConfig.canExtract(node::hasRedstoneSignal);

                if (canInsert) {
                    insertConnections.add(connection);
                    insertConnectionsByChannel.put(ioConnectionConfig.insertChannel(), connection);
                }

                if (canExtract) {
                    extractConnections.add(connection);
                    extractConnectionsByChannel.put(ioConnectionConfig.extractChannel(), connection);
                }

                // Now handle the mappings between them, do it after both are added in case we
                // can self-feed.
                if (canInsert) {
                    for (var accessibleConnection : extractConnectionsByChannel.get(ioConnectionConfig.insertChannel())) {
                        findBestPathTo(connection, accessibleConnection).ifPresent(path -> {
                            var extractPaths = extractConnectionsByInsert.computeIfAbsent(connection, k -> new ArrayList<>());
                            if (!extractPaths.contains(path)) {
                                extractPaths.add(path);
                            }

                            var insertPaths = insertConnectionsByExtract.computeIfAbsent(accessibleConnection, k -> new ArrayList<>());
                            if (!insertPaths.contains(path.reverse())) {
                                insertPaths.add(path.reverse());
                            }
                        });
                    }
                }

                if (canExtract) {
                    for (var accessibleConnection : insertConnectionsByChannel.get(ioConnectionConfig.extractChannel())) {
                        findBestPathTo(connection, accessibleConnection).ifPresent(path -> {
                            var insertPaths = insertConnectionsByExtract.computeIfAbsent(connection, k -> new ArrayList<>());
                            if (!insertPaths.contains(path)) {
                                insertPaths.add(path);
                            }

                            var extractPaths = extractConnectionsByInsert.computeIfAbsent(accessibleConnection, k -> new ArrayList<>());
                            if (!extractPaths.contains(path.reverse())) {
                                extractPaths.add(path.reverse());
                            }
                        });
                    }
                }
            }

            // All lists now require sorting
            haveConnectionsChanged = true;
        }
    }

    private Optional<ConduitConnectionPath> findBestPathTo(ConduitBlockConnection from, ConduitBlockConnection to) {
        return pathfinder.findPath(from, to, this);
    }

    // region PathfindingContext Implementation

    @Override
    public Map<ConnectionPathProperty<?>, Object> collectNodeProperties(ConduitNode node) {
        Map<ConnectionPathProperty<?>, Object> values = Maps.newHashMap();
        node.conduit().value().collectNodePathProperties(node, values::put);
        return values;
    }

    // endregion

    private void removeTickingNode(ConduitNodeImpl node) {
        if (!tickingNodes.contains(node)) {
            return;
        }

        tickingNodes.remove(node);

        // Remove connections from any maps
        for (var connection : endpointConnections.get(node)) {
            // Remove this connection's maps
            accessiblePathsByConnection.remove(connection);

            // Not a fan of having to iterate, but it's probably fine.
            for (var color : DyeColor.values()) {
                insertConnections.remove(connection);
                extractConnections.remove(connection);
                insertConnectionsByChannel.remove(color, connection);
                extractConnectionsByChannel.remove(color, connection);
            }

            extractConnectionsByInsert.remove(connection);
            insertConnectionsByExtract.remove(connection);

            // Remove this connection from other maps
            for (var list : accessiblePathsByConnection.values()) {
                list.removeIf(p -> p.start() == connection || p.end() == connection);
            }

            for (var list : extractConnectionsByInsert.values()) {
                list.removeIf(p -> p.start() == connection || p.end() == connection);
            }

            for (var list : insertConnectionsByExtract.values()) {
                list.removeIf(p -> p.start() == connection || p.end() == connection);
            }

            haveConnectionsChanged = true;
        }

        // And finally remove all the connections from the main list.
        endpointConnections.removeAll(node);
    }

    private void updateChannelList() {
        allChannels.clear();
        allChannels.addAll(insertConnectionsByChannel.keySet());
        allChannels.addAll(extractConnectionsByChannel.keySet());
    }

    private void sortConnectionLists() {
        var basicConnectionComparator = conduitType.connectionComparator();
        if (basicConnectionComparator != null) {
            insertConnections.sort(basicConnectionComparator);
            extractConnections.sort(basicConnectionComparator);
        }

        for (var connectionsList : accessiblePathsByConnection.values()) {
            connectionsList.sort(conduitType.connectionPathComparator());
        }

        for (var connectionsList : extractConnectionsByInsert.values()) {
            connectionsList.sort(conduitType.connectionPathComparator());
        }

        for (var connectionsList : insertConnectionsByExtract.values()) {
            connectionsList.sort(conduitType.connectionPathComparator());
        }

        haveConnectionsChanged = false;
    }

    /**
     * Called whenever a network is created, split or merged.
     * For other network mutations, partial cache modifications are supported.
     */
    private void rebuildCache() {
        // Clear partial update lists
        dirtyNodes.clear();

        // Clear all caches
        areTickableConduitsValid = false;

        nodesByChunkPos.clear();
        tickingNodes.clear();
        endpointConnections.clear();
        accessiblePathsByConnection.clear();
        insertConnections.clear();
        extractConnections.clear();
        insertConnectionsByChannel.clear();
        extractConnectionsByChannel.clear();
        insertConnectionsByExtract.clear();
        extractConnectionsByInsert.clear();

        // Add each ticking node into the caches.
        for (var node : nodes()) {
            // Put nodes into the position map.
            addNodeToPositionMaps(node, true);

            if (node.isTicking()) {
                addTickingNode(node);
            }
        }

        // Populate channel set
        updateChannelList();

        // Sort all lists
        sortConnectionLists();

        // Fire chunk coverage update
        if (onChunkCoverageChanged != null) {
            onChunkCoverageChanged.accept(this);
        }

        // Rebuild complete
        shouldRebuildCache = false;
        haveConnectionsChanged = false;
    }

    private void addNodeToPositionMaps(ConduitNodeImpl node, boolean isRebuild) {
        // Put nodes into the position map.
        long chunk = ChunkPos.asLong(node.pos());
        boolean isNewChunk = !nodesByChunkPos.containsKey(chunk);
        nodesByChunkPos.put(chunk, node);

        if (!isRebuild && isNewChunk && onChunkCoverageChanged != null) {
            onChunkCoverageChanged.accept(this);
        }
    }

    private void removeNodeFromPositionMaps(ConduitNodeImpl node) {
        // Put nodes into the position map.
        long chunk = ChunkPos.asLong(node.pos());
        nodesByChunkPos.remove(chunk, node);

        boolean isRemovedChunk = !nodesByChunkPos.containsKey(chunk);
        if (isRemovedChunk && onChunkCoverageChanged != null) {
            onChunkCoverageChanged.accept(this);
        }
    }

    // endregion

    // region Network Impl

    @Override
    protected ConduitNetworkImpl createEmpty() {
        return new ConduitNetworkImpl(conduitType);
    }

    @Override
    protected void onNodeAdded(ConduitNodeImpl node) {
        // Always recompute what conduits can tick - it's cheap to do.
        areTickableConduitsValid = false;

        // Increment node count if loaded (constructor will initialize the values)
        if (nodeCountByConduit != null) {
            nodeCountByConduit.compute(node.conduit(), (k, count) -> count == null ? 1 : count + 1);
        }

        // If called during super constructor
        // TODO: Review this behaviour...
        if (nodesByChunkPos == null) {
            return;
        }

        if (shouldRebuildCache) {
            return;
        }

        addNodeToPositionMaps(node, false);
        dirtyNodes.add(node);
    }

    @Override
    protected void onNodeRemoved(ConduitNodeImpl node) {
        // Always recompute what conduits can tick - it's cheap to do.
        areTickableConduitsValid = false;

        // Remove from node count
        nodeCountByConduit.compute(node.conduit(), (k, count) -> count == null || count == 1 ? null : count - 1);

        if (shouldRebuildCache) {
            return;
        }

        removeNodeFromPositionMaps(node);
        if (!shouldRebuildCache) {
            dirtyNodes.add(node);
        }
    }

    @Override
    protected void onMerged(ConduitNetworkImpl other) {
        if (context != null && other.context != null) {
            context = context.mergeWith(other.castContext());
        } else if (context == null && other.context != null) {
            context = other.context;
        }

        // Fully recompute node counts
        recomputeNodeCounts();

        // The cache will need to be rebuilt
        shouldRebuildCache = true;
    }

    private <Z extends ConduitNetworkContext<Z>> Z castContext() {
        // noinspection unchecked
        return (Z) Objects.requireNonNull(context);
    }

    @Override
    protected void onGraphSplit(Set<ConduitNetworkImpl> newNetworks) {
        shouldRebuildCache = true;

        // Fully recompute node counts
        recomputeNodeCounts();

        if (context == null) {
            return;
        }

        // Collect all networks for splitting
        var allNetworks = Stream.concat(Stream.of(this), newNetworks.stream()).collect(Collectors.toSet());

        // Handle the new graphs first
        for (var newNetwork : newNetworks) {
            newNetwork.context = context.split(newNetwork, allNetworks);
            if (newNetwork.context == context) {
                throw new IllegalStateException("Splitting context for a network of '" + EnderIORegistries.CONDUIT_TYPE.getKey(conduitType)
                        + "' resulted in the same context for multiple networks.");
            }

            newNetwork.shouldRebuildCache = true;
        }

        var newContext = context.split(this, allNetworks);
        if (newContext == context) {
            throw new IllegalStateException("Splitting context for a network of '" + EnderIORegistries.CONDUIT_TYPE.getKey(conduitType)
                    + "' resulted in the same context for multiple networks.");
        }

        context = newContext;
    }

    // endregion

    public void addCrashInfo(CrashReportCategory category) {
        category.setDetail("ShouldRebuildCache", shouldRebuildCache);
        category.setDetail("HaveConnectionsChanged", haveConnectionsChanged);
        category.setDetail("NodeCount", nodeCount());
        category.setDetail("TickingNodeCount", tickingNodes.size());
        category.setDetail("NodesByChunkPos", nodesByChunkPos.size());
        category.setDetail("DirtyNodes", dirtyNodes.size());
        category.setDetail("AllChannels", allChannels.size());
        category.setDetail("InsertConnections", insertConnections.size());
        category.setDetail("ExtractConnections", extractConnections.size());
    }
}

package com.enderio.enderio.content.conduits.network;

import com.enderio.core.common.graph.INetworkNode;
import com.enderio.enderio.api.conduits.Conduit;
import com.enderio.enderio.api.conduits.connection.ConnectionStatus;
import com.enderio.enderio.api.conduits.connection.config.ConnectionConfig;
import com.enderio.enderio.api.conduits.connection.config.ConnectionConfigType;
import com.enderio.enderio.api.conduits.network.node.ConduitNode;
import com.enderio.enderio.api.conduits.network.node.NodeData;
import com.enderio.enderio.api.conduits.network.node.NodeDataType;
import com.enderio.enderio.content.conduits.legacy.ConduitDataContainer;
import com.google.common.base.Preconditions;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.Holder;
import net.minecraft.world.item.DyeColor;
import net.neoforged.neoforge.capabilities.BlockCapability;
import net.neoforged.neoforge.items.IItemHandlerModifiable;
import org.jetbrains.annotations.Nullable;

import java.util.Objects;
import java.util.Optional;

public final class ConduitNodeImpl implements INetworkNode<ConduitNetworkImpl, ConduitNodeImpl>, ConduitNode {

    // TODO: 1.22 - Remove legacy codec.
    public static final Codec<ConduitNodeImpl> LEGACY_V7_CODEC = RecordCodecBuilder.create(instance -> instance
            .group(BlockPos.CODEC.fieldOf("pos").forGetter(ConduitNodeImpl::pos),
                    ConduitDataContainer.CODEC.fieldOf("data").forGetter(i -> i.legacyDataContainer))
            .apply(instance, ConduitNodeImpl::new));

    // Just for tests.
    public static final Codec<ConduitNodeImpl> LEGACY_V8_0_CODEC = RecordCodecBuilder
        .create(instance -> instance.group(BlockPos.CODEC.fieldOf("pos").forGetter(ConduitNodeImpl::pos),
                NodeData.GENERIC_CODEC.optionalFieldOf("data")
                    .forGetter(i -> i.nodeData == null || !i.nodeData.type().isPersistent() ? Optional.empty()
                        : Optional.of(i.nodeData)))
            .apply(instance, ConduitNodeImpl::new));

    public static final Codec<ConduitNodeImpl> NEW_CODEC = RecordCodecBuilder
            .create(instance -> instance.group(
                Conduit.CODEC.optionalFieldOf("conduit").forGetter(node -> Optional.ofNullable(node.conduit)),
                BlockPos.CODEC.fieldOf("pos").forGetter(ConduitNodeImpl::pos),
                    NodeData.GENERIC_CODEC.optionalFieldOf("data")
                            .forGetter(i -> i.nodeData == null || !i.nodeData.type().isPersistent() ? Optional.empty()
                                    : Optional.of(i.nodeData)))
                    .apply(instance, ConduitNodeImpl::new));

    public static final Codec<ConduitNodeImpl> CODEC = Codec.withAlternative(NEW_CODEC, LEGACY_V7_CODEC);

    // TODO: final in 21.11
    @Nullable
    private Holder<Conduit<?, ?>> conduit;
    private final BlockPos pos;

    @Nullable
    private NodeData nodeData;

    // TODO: Remove in 21.11
    @Nullable
    private ConduitDataContainer legacyDataContainer = null;

    @Nullable
    private ConduitNetworkImpl network;

    @Nullable
    private IConduitNodeAttachment conduitBundle;

    public ConduitNodeImpl(Holder<Conduit<?, ?>> conduit, BlockPos pos) {
        this(conduit, pos, (NodeData) null);
    }

    public ConduitNodeImpl(Holder<Conduit<?, ?>> conduit, BlockPos pos, @Nullable NodeData nodeData) {
        this.conduit = conduit;
        this.pos = pos;
        this.nodeData = nodeData;
        this.network = new ConduitNetworkImpl(conduit.value().type(), this);
    }

    public ConduitNodeImpl(Holder<Conduit<?, ?>> conduit, BlockPos pos, ConduitDataContainer legacyDataContainer) {
        this(conduit, pos, (NodeData) null);

        // Extract node data from legacy data
        var oldData = legacyDataContainer.getData();
        if (oldData != null) {
            // Store for copyLegacyData once we have a network.
            this.legacyDataContainer = legacyDataContainer;
            this.nodeData = oldData.toNodeData();
        }
    }

    private ConduitNodeImpl(Optional<Holder<Conduit<?, ?>>> conduit, BlockPos pos, Optional<NodeData> nodeData) {
        this.conduit = conduit.orElse(null);
        this.pos = pos;
        this.nodeData = nodeData.orElse(null);
    }

    @SuppressWarnings("OptionalUsedAsFieldOrParameterType")
    private ConduitNodeImpl(BlockPos pos, Optional<NodeData> nodeData) {
        this.pos = pos;
        this.nodeData = nodeData.orElse(null);
        // Does not create a network because we're loading.
    }

    private ConduitNodeImpl(BlockPos pos, ConduitDataContainer legacyDataContainer) {
        this(pos, Optional.empty());

        // Extract node data from legacy data
        var oldData = legacyDataContainer.getData();
        if (oldData != null) {
            // Store for copyLegacyData once we have a network.
            this.legacyDataContainer = legacyDataContainer;
            this.nodeData = oldData.toNodeData();
        }
    }

    // Intended for loading from the old network format.
    @Deprecated
    public void setConduitIfNull(Holder<Conduit<?, ?>> conduit) {
        if (this.conduit == null) {
            this.conduit = conduit;
        }
    }

    public void attach(IConduitNodeAttachment conduitBundle) {
        Preconditions.checkState(network != null, "Conduit node is not connected to a network.");
        this.conduitBundle = conduitBundle;
        network.onNodeUpdated(this);
        tryCopyLegacyData();
    }

    public void detach() {
        if (conduitBundle == null) {
            return;
        }

        this.conduitBundle = null;

        if (network != null) {
            network.onNodeUpdated(this);
        }
    }

    public void onConfigChanged() {
        if (network != null) {
            network.onNodeUpdated(this);
        }
    }

    public void onRedstoneChanged() {
        if (network != null) {
            network.onNodeUpdated(this);
        }
    }

    @Override
    public Holder<Conduit<?, ?>> conduit() {
        return conduit;
    }

    @Override
    public BlockPos pos() {
        return pos;
    }

    @Override
    public boolean isLoaded() {
        if (!isValid() || conduitBundle == null) {
            return false;
        }

        return conduitBundle.hasLevel() && conduitBundle.getLevel().isLoaded(pos);
    }

    @Override
    public boolean isTicking() {
        return isLoaded() && conduitBundle.getLevel().shouldTickBlocksAt(pos);
    }

    @Override
    public void markDirty() {
        // No-op if we're loading chunks, just in case.
        if (isLoaded()) {
            // noinspection DataFlowIssue
            conduitBundle.markNodesDirty();
        }
    }

    // region Node Data

    @Override
    public boolean hasNodeData(NodeDataType<?> type) {
        return nodeData != null && nodeData.type() == type;
    }

    @Override
    @Nullable
    public NodeData getNodeData() {
        return nodeData;
    }

    @Override
    @Nullable
    public <D extends NodeData> D getNodeData(NodeDataType<D> type) {
        if (nodeData != null && type == nodeData.type()) {
            // noinspection unchecked
            return (D) nodeData;
        }

        return null;
    }

    @Override
    public <D extends NodeData> D getOrCreateNodeData(NodeDataType<D> type) {
        if (nodeData != null && type == nodeData.type()) {
            // noinspection unchecked
            return (D) nodeData;
        }

        nodeData = type.create();
        // noinspection unchecked
        return (D) nodeData;
    }

    @Override
    public <D extends NodeData> void setNodeData(@Nullable D data) {
        nodeData = data;
    }

    // endregion

    // region World Interaction

    @Override
    public @Nullable <T, C> T getCapability(BlockCapability<T, C> capability, Direction neighborSide, @Nullable C context) {
        ensureValid();
        // noinspection DataFlowIssue
        return conduitBundle.getCapability(conduit, capability, neighborSide, context);
    }

    @Override
    public boolean hasRedstoneSignal(@Nullable DyeColor signalColor) {
        ensureValid();
        // noinspection DataFlowIssue
        return conduitBundle.hasRedstoneSignal(signalColor);
    }

    // endregion

    // region Connections

    @Override
    public ConnectionStatus getConnectionStatus(Direction side) {
        ensureValid();
        // noinspection DataFlowIssue
        return conduitBundle.getConnectionStatus(conduit, side);
    }

    @Override
    public ConnectionConfig getConnectionConfig(Direction side) {
        ensureValid();
        // noinspection DataFlowIssue
        return conduitBundle.getConnectionConfig(conduit, side);
    }

    // endregion

    // region Inventory

    @Override
    public IItemHandlerModifiable getInventory(Direction side) {
        ensureValid();

        // We don't have to do this, but it saves null checks in the tickers.
        // Only tickers that know they have inventories should use this anyway.
        // noinspection DataFlowIssue
        var inventory = conduitBundle.getConnectionInventory(conduit, side);
        if (inventory == null) {
            throw new IllegalStateException("This conduit does not have an inventory!");
        }

        return inventory;
    }

    // endregion

    // region Network Node Impl

    @Override
    public boolean isValid() {
        return network != null;
    }

    @Override
    public ConduitNetworkImpl getNetwork() {
        return Objects.requireNonNull(network, "Node is not valid!");
    }

    @Override
    public void setNetwork(@Nullable ConduitNetworkImpl network) {
        this.network = network;
        tryCopyLegacyData();
    }

    // endregion

    private void ensureValid() {
        Preconditions.checkState(network != null, "Conduit node is not connected to a network.");
        Preconditions.checkState(conduitBundle != null, "Conduit node is detached.");
        Preconditions.checkState(conduitBundle.hasLevel(), "Conduit bundle is not attached to a level");
        Preconditions.checkState(conduitBundle.getLevel().isLoaded(pos), "Conduit bundle is not loaded in a loaded chunk");
        Preconditions.checkState(isLoaded(), "Conduit node is not loaded - more specific error unavailable.");
    }

    private void tryCopyLegacyData() {
        if (this.conduit != null&& legacyDataContainer != null) {
            // We now know what type of conduit we are, so upgrade the connection data then
            // drop legacy data
            this.conduit
                    .value()
                    .copyLegacyData(this, legacyDataContainer,
                            (side, config) -> conduitBundle.setConnectionConfig(conduit, side, config));
            legacyDataContainer = null;
        }
    }
}

package com.enderio.core.common.graph;

import com.google.common.base.Preconditions;
import com.google.common.collect.Queues;
import com.google.common.collect.Sets;
import com.google.common.graph.ElementOrder;
import com.google.common.graph.GraphBuilder;
import com.google.common.graph.MutableGraph;
import com.mojang.datafixers.Products;
import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import org.jetbrains.annotations.Nullable;

import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Stream;

/**
 * A graph-backed network structure, with support for merging and splitting networks.
 *
 * @param <TNet> The network implementation type.
 * @param <TNode> The node type for this network.
 */
@SuppressWarnings("UnstableApiUsage")
public abstract class Network<TNet extends Network<TNet, TNode>, TNode extends INetworkNode<TNet, TNode>> {

    // The underlying graph.
    // Uses stable element ordering to ensure consistent behavior when serializing
    // the graph.
    final MutableGraph<TNode> graph = GraphBuilder.undirected()
            .allowsSelfLoops(false)
            .nodeOrder(ElementOrder.stable())
            .incidentEdgeOrder(ElementOrder.stable())
            .build();

    // Whether the network has been discarded due to a merge.
    boolean isDiscarded;

    /**
     * Create a network with a single starting node.
     * @param initialNode The initial node. This node must not be attached to any other graphs.
     */
    protected Network(TNode initialNode) {
        this(List.of(initialNode), List.of());
    }

    /**
     * Create a network with a pre-configured set of edges.
     * @param nodes All the nodes in this network. None may be attached to another network.
     * @param edges All the edges linking nodes together. Edges must reflect the nodes in the {@code nodes} list.
     */
    protected Network(List<TNode> nodes, List<Pair<TNode, TNode>> edges) {
        // Ensure there's at least one edge.
        Preconditions.checkArgument(!nodes.isEmpty(), "Cannot create a network with no nodes.");
        Preconditions.checkArgument(nodes.stream().noneMatch(INetworkNode::isValid),
                "Some nodes are already in networks.");

        // Special case for a single starting node
        if (nodes.size() == 1) {
            Preconditions.checkArgument(edges.isEmpty(), "A single node cannot have any edges.");
            var node = nodes.getFirst();
            graph.addNode(node);
            node.setNetwork(self());
            onNodeAdded(node);
            return;
        }

        // If some of these nodes are already in networks, the caller should use
        // connect/connectMany instead.
        Preconditions.checkArgument(
                edges.stream().allMatch(e -> nodes.contains(e.getFirst()) && nodes.contains(e.getSecond())),
                "Some edges reference nodes that were not included in the node list.");

        // Add all nodes
        for (var node : nodes) {
            graph.addNode(node);
            node.setNetwork(self());
            onNodeAdded(node);
        }

        // Add all edges (and nodes)
        for (var edge : edges) {
            graph.putEdge(edge.getFirst(), edge.getSecond());
            onNodesConnected(edge.getFirst(), edge.getSecond());
        }
    }

    /**
     * Create a network with a pre-configured set of edges, represented as pairs of indices into {@code nodes}.
     * This is intended for use during serialization/deserialization.
     * @param nodes All the nodes in this network. None may be attached to another network.
     * @param edges All the edges linking nodes together, indexing nodes in {@code nodes}.
     */
    protected Network(List<TNode> nodes, IndexedEdgeList edges) {
        this(nodes, edges.expand(nodes));
    }

    /**
     * This constructor is used when merging graphs and thus can be initialized with no nodes.
     * This constructor should never be made public. Use {@link Network#Network(INetworkNode)}} instead.
     */
    protected Network() {
    }

